import React, { useState, useEffect, useContext } from "react";
import { useLocation } from "react-router-dom";
import SidebarTeacher from "../components/SidebarTeacher";
import axiosInstance from "../api/axios";
import { AuthContext } from "../context/AuthContext";
import "../global.css";

const students = [
  { rollNo: "CS20B001", name: "Aarav Sharma", marks: "" },
  { rollNo: "CS20B002", name: "Diya Patel", marks: "" },
  { rollNo: "CS20B003", name: "Rohan Kumar", marks: "" },
  { rollNo: "CS20B004", name: "Priya Singh", marks: "" },
  { rollNo: "CS20B005", name: "Vikram Reddy", marks: "" }
];

const departments = ["Select Department", "Computer Science", "Information Tech"];
const classes = ["Select Class", "First Year", "Second Year", "Third Year"];
const sections = ["Select Section", "A", "B", "C"];
const subjects = ["Select Subject", "Data Structures", "DBMS", "OS"];

export default function EnterMarks() {
  const { user } = useContext(AuthContext);
  const location = useLocation();

  const [studentList, setStudentList] = useState(students);
  const [department, setDepartment] = useState("");
  const [className, setClassName] = useState("");
  const [section, setSection] = useState("");
  const [subject, setSubject] = useState("");
  const [category, setCategory] = useState("IAT");

  // Infer category from path (/iat, /lab, /assignment)
  useEffect(() => {
    const p = location.pathname.toLowerCase();
    if (p.includes("lab")) setCategory("Lab");
    else if (p.includes("assignment")) setCategory("Assignment");
    else if (p.includes("iat")) setCategory("IAT");
  }, [location.pathname]);

  const handleMarkChange = (idx, value) => {
    const updated = studentList.map((student, i) =>
      i === idx ? { ...student, marks: value } : student
    );
    setStudentList(updated);
  };

  const handleSave = async () => {
    try {
      const payloads = studentList
        .filter(s => s.marks !== "")
        .map(s => ({
          studentId: s.rollNo, // TODO: replace with ObjectId mapping if available
          subject,
          marks: Number(s.marks),
          teacherId: user?.id,
          category,
        }));

      await Promise.all(payloads.map(p => axiosInstance.post('/marks', p)));
      alert("Marks saved to database!");
    } catch (err) {
      console.error(err);
      alert("Failed to save marks");
    }
  };

  return (
    <div className="dashboard-flex">
      <SidebarTeacher active="Enter Marks" />

      <div className="entermarks-main">
        <header className="entermarks-header">
          <span className="header-title">Enter {category} Marks</span>
          <div className="header-actions">
            <input className="search" placeholder="Search for students, subjects..." />
            <i className="fa-regular fa-bell"></i>
            <i className="fa-solid fa-gear"></i>
          </div>
        </header>
        <div className="entermarks-form-block">
          <div className="entermarks-form-row">
            <select value={department} onChange={e=>setDepartment(e.target.value)}>
              {departments.map(opt=> <option key={opt} value={opt}>{opt}</option>)}
            </select>
            <select value={className} onChange={e=>setClassName(e.target.value)}>
              {classes.map(opt=> <option key={opt} value={opt}>{opt}</option>)}
            </select>
            <select value={section} onChange={e=>setSection(e.target.value)}>
              {sections.map(opt=> <option key={opt} value={opt}>{opt}</option>)}
            </select>
            <select value={subject} onChange={e=>setSubject(e.target.value)}>
              {subjects.map(opt=> <option key={opt} value={opt}>{opt}</option>)}
            </select>
            <select value={category} onChange={e=>setCategory(e.target.value)}>
              {['IAT','Lab','Assignment'].map(opt=> <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="entermarks-table-block">
            <table className="entermarks-table">
              <thead>
                <tr>
                  <th>Roll No</th>
                  <th>Student Name</th>
                  <th>Marks</th>
                </tr>
              </thead>
              <tbody>
                {studentList.map((s, i) => (
                  <tr key={s.rollNo}>
                    <td>{s.rollNo}</td>
                    <td>{s.name}</td>
                    <td>
                      <input
                        className="marks-input"
                        type="number"
                        min="0"
                        max="100"
                        placeholder="Max: 100"
                        value={s.marks}
                        onChange={e=>handleMarkChange(i, e.target.value)}
                      />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {/* Lab uploads placeholder section (to be wired to /api/lab-records later) */}
            {category === 'Lab' && (
              <div style={{marginTop: 16}}>
                <div className="muted">Uploaded Lab Records (placeholder)</div>
                <ul className="muted">
                  <li>Chemistry Lab - Week 3 - John Doe.pdf</li>
                  <li>Physics Lab - Week 2 - Jane Smith.pdf</li>
                </ul>
              </div>
            )}

            <div className="entermarks-save-btn-row">
              <button className="entermarks-save-btn" onClick={handleSave}>Save Marks</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
